const express = require('express');
const { RateLimiterRedis } = require('rate-limiter-flexible');
const Redis = require('ioredis');

const app = express();
const redisClient = new Redis(process.env.REDIS_URL);

const apiLimiter = new RateLimiterRedis({
  storeClient: redisClient,
  keyPrefix: 'api_quota',
  points: 50000,
  duration: 86400
});

app.get('/api/v1/rate-limits/tenants/:tenantId/usage', async (req, res) => {
  if (!req.user || !req.user.tenantId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { tenantId } = req.params;

  // Enforce that callers can only view rate limit metrics for their own tenant
  if (req.user.tenantId !== tenantId) {
    return res.status(403).json({ error: 'Forbidden: cannot inspect usage of another tenant' });
  }

  const rateLimitRes = await apiLimiter.get(tenantId);
  if (!rateLimitRes) {
    return res.json({ tenantId, consumedPoints: 0, remainingPoints: 50000 });
  }

  res.json({
    tenantId,
    consumedPoints: rateLimitRes.consumedPoints,
    remainingPoints: rateLimitRes.remainingPoints,
    msBeforeNextReset: rateLimitRes.msBeforeNext
  });
});

app.listen(9002);
